from fractions import Fraction as F

def dot(a,b):return sum(x*y for x,y in zip(a,b))
def add(a,b):return tuple(x+y for x,y in zip(a,b))
def mul(t,a):return tuple(t*x for x in a)
def mgda(a,b):
    d=tuple(x-y for x,y in zip(a,b))
    t=max(F(0),min(F(1),-dot(b,d)/dot(d,d))) if dot(d,d) else F(0)
    return add(mul(t,a),mul(1-t,b))
a=[(F(2),F(0)),(F(0),F(2))]
b=[(F(-4),F(0)),(F(0),F(-1,2))]
l=mgda(*a);f=mgda(*b);dec=add(l,f)
h=[add(x,y) for x,y in zip(a,b)];direct=mgda(*h)
for name,x in [('loss aggregate',l),('flat aggregate',f),('decomposed update',dec),('direct update',direct)]: print(name,tuple(str(v) for v in x))
print('Theorem 5 assumptions:', [float(dot(f,x)) for x in a], [float(dot(l,x)) for x in b])
print('First-order objective decreases, decomposed:',[float(dot(dec,x)) for x in h])
print('First-order objective decreases, direct:',[float(dot(direct,x)) for x in h])

def hval(theta,i):
    x,y=theta
    if i==0:return F(10)+2*x-2*x*x+abs(2-4*x)
    return F(10)+2*y-y*y/4+abs(2-y/2)
eta=F(1,100)
for i in [0,1]:print('Objective',i+1,'initial',float(hval((F(0),F(0)),i)),'decomposed',float(hval(mul(-eta,dec),i)),'direct',float(hval(mul(-eta,direct),i)))
